import { IOStateData } from '../data/IOStateData';
import { MessageEvent } from '../data/SignalR/SignalREventTypes';
import { LogCategory, Logger } from './Logger';
import { SignalRManager } from './SignalRManager';

/**
 * SignalRIOUpdater - Listens for I/O status messages and updates IOStateData
 * Handles messages like:
 * - "S198 Output 7 On" 
 * - "S134 Input 7 Closed"
 * - "S135 Input 7 Open"
 */
export class SignalRIOUpdater {
    private static _instance: SignalRIOUpdater;
    private _isListening: boolean = false;

    private constructor() {
        // Private constructor for singleton pattern
    }

    /**
     * Get the singleton instance
     */
    public static get Instance(): SignalRIOUpdater {
        if (!SignalRIOUpdater._instance) {
            SignalRIOUpdater._instance = new SignalRIOUpdater();
        }
        return SignalRIOUpdater._instance;
    }

    /**
     * Start listening for I/O status messages
     */
    public startListening(): void {
        if (this._isListening) {
            return;
        }

        SignalRManager.Instance.addEventListener('MessageEvent', this._handleMessageEvent);
        this._isListening = true;

        Logger.Instance.log(LogCategory.DataManager, 'SignalRIOUpdater started listening for I/O status messages');
    }

    /**
     * Stop listening for I/O status messages
     */
    public stopListening(): void {
        if (!this._isListening) {
            return;
        }

        SignalRManager.Instance.removeEventListener('MessageEvent', this._handleMessageEvent);
        this._isListening = false;

        Logger.Instance.log(LogCategory.DataManager, 'SignalRIOUpdater stopped listening for I/O status messages');
    }

    /**
     * Handle MessageEvent from SignalR and parse I/O status messages
     */
    private _handleMessageEvent = (event: MessageEvent): void => {
        try {
            const message = event.data.message;
            if (!message) {
                return;
            }

            Logger.Instance.log(
                LogCategory.DataManager,
                `SignalRIOUpdater: Checking message: "${message}"`
            );

            // Parse I/O status messages
            const ioUpdate = this._parseIOStatusMessage(message);
            if (ioUpdate) {
                Logger.Instance.log(
                    LogCategory.DataManager,
                    `SignalRIOUpdater: Parsed I/O update - type=${ioUpdate.type}, number=${ioUpdate.number}, isActive=${ioUpdate.isActive}`
                );

                // Enhance the message with I/O name and custom text (BEFORE updating state)
                this._enhanceMessageWithIOInfo(event, ioUpdate);

                // Update I/O state immediately
                this._updateIOState(ioUpdate);
            }
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Error handling I/O message event:', error);
        }
    };    /**
     * Parse I/O status messages into structured data
     * @param message The raw message string (e.g., "S198 Output 7 On")
     * @returns Parsed I/O update or null if not an I/O message
     */
    private _parseIOStatusMessage(message: string): IOStatusUpdate | null {
        // Match patterns (with or without 'S' prefix):
        // S198 Output 7 On  OR  5198 Output 7 On
        // S134 Input 7 Closed  OR  5134 Input 7 Closed
        // S135 Input 7 Open  OR  5135 Input 7 Open
        const outputPattern = /^S?\d+\s+Output\s+(\d+)\s+(On|Off)$/i;
        const inputPattern = /^S?\d+\s+Input\s+(\d+)\s+(Closed|Open)$/i;

        let match = message.match(outputPattern);
        if (match) {
            const number = parseInt(match[1], 10);
            const isActive = match[2].toLowerCase() === 'on';
            Logger.Instance.log(
                LogCategory.DataManager,
                `SignalRIOUpdater: Parsed OUTPUT ${number} = ${isActive ? 'ON' : 'OFF'} from message: "${message}"`
            );
            return {
                type: 'output',
                number,
                isActive,
                originalMessage: message
            };
        }

        match = message.match(inputPattern);
        if (match) {
            const number = parseInt(match[1], 10);
            const isActive = match[2].toLowerCase() === 'closed';
            Logger.Instance.log(
                LogCategory.DataManager,
                `SignalRIOUpdater: Parsed INPUT ${number} = ${isActive ? 'CLOSED' : 'OPEN'} from message: "${message}"`
            );
            return {
                type: 'input',
                number,
                isActive,
                originalMessage: message
            };
        }

        Logger.Instance.log(
            LogCategory.DataManager,
            `SignalRIOUpdater: Message did NOT match I/O patterns: "${message}"`
        );
        return null;
    }

    /**
     * Enhance the MessageEvent with custom I/O information
     * Updates the message to include the I/O name and custom active/inactive text
     */
    private _enhanceMessageWithIOInfo(event: MessageEvent, update: IOStatusUpdate): void {
        if (!IOStateData.Instance.isInitialized) {
            return;
        }

        try {
            let ioItem;
            let displayName: string;
            let statusText: string;

            if (update.type === 'input') {
                ioItem = IOStateData.Instance.getInputByNumber(update.number);

                // Use custom name if available
                displayName = this._formatIOName(ioItem?.name, ioItem?.centroidName);
                if (!displayName) {
                    displayName = `Input ${update.number}`;
                } else {
                    displayName = `Input ${update.number} (${displayName})`;
                }

                // Use custom active/inactive text
                statusText = update.isActive
                    ? (ioItem?.activeText || 'Active')
                    : (ioItem?.inactiveText || 'Inactive');
            } else {
                ioItem = IOStateData.Instance.getOutputByNumber(update.number);

                // Use custom name if available
                displayName = this._formatIOName(ioItem?.name, ioItem?.centroidName);
                if (!displayName) {
                    displayName = `Output ${update.number}`;
                } else {
                    displayName = `Output ${update.number} (${displayName})`;
                }

                // Use custom active/inactive text
                statusText = update.isActive
                    ? (ioItem?.activeText || 'Active')
                    : (ioItem?.inactiveText || 'Inactive');
            }

            // Update the message event data with enhanced information
            const originalMessage = event.data.message;
            event.data.message = `${displayName}: ${statusText}`;

            Logger.Instance.log(
                LogCategory.DataManager,
                `SignalRIOUpdater: Enhanced message from "${originalMessage}" to "${event.data.message}"`
            );
        } catch (error) {
            Logger.Instance.logError(
                LogCategory.DataManager,
                'Error enhancing message with I/O info:',
                error
            );
        }
    }

    /**
     * Update IOStateData with the parsed I/O status
     */
    private _updateIOState(update: IOStatusUpdate): void {
        if (!IOStateData.Instance.isInitialized) {
            Logger.Instance.log(LogCategory.DataManager, 'IOStateData not initialized - skipping I/O update');
            return;
        }

        try {
            if (update.type === 'input') {
                const input = IOStateData.Instance.getInputByNumber(update.number);
                const oldState = input?.isActive;

                Logger.Instance.log(
                    LogCategory.DataManager,
                    `SignalRIOUpdater: Updating input ${update.number} from ${oldState} to ${update.isActive}`
                );

                IOStateData.Instance.updateInputState(update.number, update.isActive);

                const inputName = this._formatIOName(input?.name, input?.centroidName);
                const displayName = inputName ? `input ${update.number} (${inputName})` : `input ${update.number}`;

                Logger.Instance.log(
                    LogCategory.DataManager,
                    `Updated ${displayName} to ${update.isActive ? 'ACTIVE' : 'INACTIVE'} via SignalR`
                );
            } else if (update.type === 'output') {
                const output = IOStateData.Instance.getOutputByNumber(update.number);
                const oldState = output?.isActive;

                Logger.Instance.log(
                    LogCategory.DataManager,
                    `SignalRIOUpdater: Updating output ${update.number} from ${oldState} to ${update.isActive}`
                );

                IOStateData.Instance.updateOutputState(update.number, update.isActive);

                const outputName = this._formatIOName(output?.name, output?.centroidName);
                const displayName = outputName ? `output ${update.number} (${outputName})` : `output ${update.number}`;

                Logger.Instance.log(
                    LogCategory.DataManager,
                    `Updated ${displayName} to ${update.isActive ? 'ACTIVE' : 'INACTIVE'} via SignalR`
                );
            }
        } catch (error) {
            Logger.Instance.logError(
                LogCategory.DataManager,
                `Error updating ${update.type} ${update.number} state:`,
                error
            );
        }
    }

    /**
     * Format I/O name for display. Prefers custom name, falls back to centroid name.
     * @param customName Custom user-defined name
     * @param centroidName Standard centroid name
     * @returns Formatted name or empty string if no name available
     */
    private _formatIOName(customName?: string, centroidName?: string): string {
        // Prefer custom name if available
        if (customName && customName.trim()) {
            return customName;
        }
        // Fall back to centroid name
        if (centroidName && centroidName.trim()) {
            return centroidName;
        }
        return '';
    }

    /**
     * Get current listening status
     */
    public get isListening(): boolean {
        return this._isListening;
    }
}

/**
 * Parsed I/O status update
 */
interface IOStatusUpdate {
    type: 'input' | 'output';
    number: number;
    isActive: boolean;
    originalMessage: string;
}